public class SortingString {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
//		char c[]= {'D','S','Y','R','O'};
		String s[]= {"hello","sindhu","john","scott","merry"};
		
		System.out.println(Arrays.toString(s));
		
		Arrays.sort(s);
		System.out.println(Arrays.toString(s));
		
		

	}

}
